  "Teacher": { en: "Teacher", hi: "शिक्षक", mr: "शिक्षक", ta: "ஆசிரியர்", bn: "শিক্ষক", ur: "استاد" },
  "Marketing Manager": { en: "Marketing Manager", hi: "मार्केटिंग मैनेजर", mr: "मार्केटिंग मॅनेजर", ta: "மார்க்கெட்டிங் மேலாளர்", bn: "মার্কেটিং ম্যানেজার", ur: "مارکیٹنگ مینیجر" },
  "Sales Executive": { en: "Sales Executive", hi: "सेल्स एग्जीक्यूटिव", mr: "सेल्स एग्झिक्युटिव्ह", ta: "விற்பனை நிர்வாகி", bn: "সেলস এক্সিকিউটিভ", ur: "سیلز ایگزیکٹو" },
  "Web Developer": { en: "Web Developer", hi: "वेब डेवलपर", mr: "वेब डेव्हलपर", ta: "வெப் டெவலப்பர்", bn: "ওয়েব ডেভেলপার", ur: "ویب ڈویلپر" },
  "Mechanic": { en: "Mechanic", hi: "मैकेनिक", mr: "मेकॅनिक", ta: "மெக்கானிக்", bn: "মেকানিক", ur: "مکینک" },
