  "Software Engineer": { en: "Software Engineer", hi: "सॉफ्टवेयर इंजीनियर", mr: "सॉफ्टवेअर इंजिनिअर", ta: "மென்பொருள் பொறியாளர்", bn: "সফটওয়্যার ইঞ্জিনিয়ার", ur: "سافٹ ویئر انجینئر" },
  "Helper": { en: "Helper", hi: "हेल्पर", mr: "मदतनीस", ta: "உதவியாளர்", bn: "হেল্পার", ur: "ہیلپر" },
  "Delivery Executive": { en: "Delivery Executive", hi: "डिलीवरी एग्जीक्यूटिव", mr: "डिलिव्हरी एग्झिक्युटिव्ह", ta: "டெலிவரி நிர்வாகி", bn: "ডেলিভারি এক্সিকিউটিভ", ur: "ڈیلیوری ایگزیکٹو" },
  "Security Guard": { en: "Security Guard", hi: "सुरक्षा गार्ड", mr: "सुरक्षा रक्षक", ta: "பாதுகாவலர்", bn: "নিরাপত্তা রক্ষী", ur: "سیکیورٹی گارڈ" },
  "Warehouse Associate": { en: "Warehouse Associate", hi: "वेयरहाउस एसोसिएट", mr: "वेअरहाउस असोसिएट", ta: "கிடங்கு உதவியாளர்", bn: "ওয়্যারহাউস অ্যাসোসিয়েট", ur: "ویئر ہاؤس ایسوسی ایٹ" },
  "Graphic Designer": { en: "Graphic Designer", hi: "ग्राफिक डिज़ाइनर", mr: "ग्राफिक डिझायनर", ta: "கிராஃபிக் டிசைனர்", bn: "গ্রাফিক ডিজাইনার", ur: "گرافک ڈیزائنر" },
  "Content Writer": { en: "Content Writer", hi: "कंटेंट राइटर", mr: "कंटेंट रायटर", ta: "உள்ளடக்க எழுத்தாளர்", bn: "কন্টেন্ট রাইটার", ur: "کنٹینٹ رائٹر" },
